const sd=$getWorkflowStaticData('global'); if(!sd.drafts) sd.drafts=[];
const b=$json.body||{};
const amtNum=parseFloat((''+(b.amount||'')).replace(/[^0-9.]/g,''))||0;
const cents=Math.round(amtNum*100);
const id='sq'+Date.now().toString(36);
const draft={id, kind:'square_invoice', target:(b.customer||''),
  payload:{customer:(b.customer||''), amount_cents:cents, note:(b.note||'')},
  status:'pending', createdAt:new Date().toISOString()};
sd.drafts.push(draft);
const preview=`$${(cents/100).toFixed(2)} to ${b.customer||'(no customer)'}${b.note?(' for '+b.note):''}`;
return [{json:{summary:`Invoice draft ${id} staged: ${preview}. Nothing was created in Square. To create it as a Square DRAFT (for you to review and send yourself), approve draft ${id}.`}}];

const sd=$getWorkflowStaticData('global'); const ds=sd.drafts||[];
const id=(($json.body)||{}).id;
const d=ds.find(x=>x.id===id && x.kind==='square_invoice');
if(!d) return [{json:{ok:false, summary:`No staged Square invoice draft "${id}" found. Ask me to draft one first, then approve that id.`}}];
if(d.status==='published') return [{json:{ok:false, summary:`Draft ${id} was already created in Square (invoice #${d.invoiceNumber||'?'}).`}}];
if(!d.payload.amount_cents||d.payload.amount_cents<=0) return [{json:{ok:false, summary:`Draft ${id} has no valid amount; re-draft it.`}}];
const cust=((d.payload.customer||'')+'').trim();
const email=(cust.match(/[^\s]+@[^\s]+\.[^\s]+/)||[])[0]||'';
if(!email) return [{json:{ok:false, summary:`Draft ${id} has no email address. Square invoices need a valid customer email — re-draft with the customer's email.`}}];
const name=cust.replace(email,'').replace(/[<>,]/g,'').trim();
const custSearchBody=JSON.stringify({query:{filter:{email_address:{fuzzy:email}}},limit:1});
return [{json:{ok:true, draftId:id, email, name, amount_cents:d.payload.amount_cents, note:(d.payload.note||''), custSearchBody}}];

const prep=$('Prep').first().json;
const cs=($json.customers)||[];
const found=cs[0];
const orderBody=JSON.stringify({idempotency_key:('ord'+prep.draftId+Date.now().toString(36)).slice(0,45),
  order:{location_id:'{{SQUARE_LOCATION_ID}}', line_items:[{name:((prep.note||'Service')+'').slice(0,60), quantity:'1', base_price_money:{amount:prep.amount_cents, currency:'USD'}}]}});
const createBody=JSON.stringify({idempotency_key:('cus'+prep.draftId).slice(0,45),
  given_name:(prep.name||prep.email.split('@')[0]), email_address:prep.email});
return [{json:{need_create: !found, customer_id: found?found.id:null, createBody, orderBody,
  draftId:prep.draftId, note:prep.note, amount_cents:prep.amount_cents}}];

const sd=$getWorkflowStaticData('global'); const cust=sd._pubcust;
const pj=$('PickCust').first().json;
const order=($('OrderCreate').first().json.order)||{};
const due=new Date(Date.now()+7*24*3600*1000).toISOString().slice(0,10);
const invBody=JSON.stringify({idempotency_key:('inv'+pj.draftId+Date.now().toString(36)).slice(0,45),
  invoice:{location_id:'{{SQUARE_LOCATION_ID}}', order_id:order.id, primary_recipient:{customer_id:cust},
    delivery_method:'SHARE_MANUALLY', payment_requests:[{request_type:'BALANCE', due_date:due}],
    accepted_payment_methods:{card:true}, title:((pj.note||'Invoice')+'').slice(0,60)}});
return [{json:{invBody, draftId:pj.draftId, orderId:order.id, customerId:cust}}];

const inv=($json.invoice)||null; const errs=$json.errors;
const pi=$('PrepInv').first().json;
const amt=($('PickCust').first().json.amount_cents)/100;
if(errs&&errs.length) return [{json:{summary:`Could not create the Square invoice: ${errs.map(e=>e.detail||e.code).join('; ')}. Nothing was sent to the customer.`}}];
if(!inv||!inv.id) return [{json:{summary:'Invoice creation returned no data; nothing was sent.'}}];
const sd=$getWorkflowStaticData('global'); const d=(sd.drafts||[]).find(x=>x.id===pi.draftId);
if(d){ d.status='published'; d.invoiceId=inv.id; d.invoiceNumber=inv.invoice_number; d.orderId=pi.orderId; d.publishedAt=new Date().toISOString(); }
return [{json:{summary:`Created Square DRAFT invoice #${inv.invoice_number} for $${amt.toFixed(2)} — it is now in your Square dashboard as a DRAFT for you to review and send. I did NOT send it and cannot charge anyone.`}}];

